def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def lcm(x, y, gcd_val):
    return (x * y) // gcd_val

def binary_palindrome_changes(binary_str):
    changes = 0
    n = len(binary_str)
    for i in range(n // 2):
        if binary_str[i] != binary_str[n - i - 1]:
            changes += 1
    return changes

