def circular_shift(x, shift):
    # Generate Collatz sequence's odd numbers
    n = x
    odd_numbers = []
    if n % 2 == 1:
        odd_numbers.append(n)
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        if n % 2 == 1:
            odd_numbers.append(n)
    # Now, process each number in odd_numbers with the original shift logic
    results = []
    for num in odd_numbers:
        s = str(num)
        if shift > len(s):
            shifted = s[::-1]
        else:
            shifted = s[len(s) - shift:] + s[:len(s) - shift]
        results.append(shifted)
