    def largest_prime_factor(n):
        if n == 1:
            return None
        largest = 1
        if n % 2 == 0:
            largest = 2
            while n % 2 == 0:
                n //= 2
        f = 3
        while f * f <= n:
            if n % f == 0:
                largest = f
                while n % f == 0:
                    n //= f
            f += 2
        if n > 1:
            largest = n
        return largest

    a = None
    if largest_neg is not None:
        abs_val = abs(largest_neg)
        if abs_val >= 2:
            a = largest_prime_factor(abs_val)

    b = None
    if smallest_pos is not None:
        if smallest_pos >= 2:
            b = largest_prime_factor(smallest_pos)

    return (a, b)

