        # Check if the filename contains exactly one dot
        if file_name.count('.') != 1:
            validation_errors.append('File name must contain exactly one dot.')
            is_valid = False

        # Check for presence of dot and extract base_name and extension
        if '.' in file_name:
            base_name, extension = file_name.rsplit('.', 1)
            is_dot_present = True
        else:
            base_name = file_name
            extension = ''
            is_dot_present = False

        total_chars = len(file_name)
        base_name_length = len(base_name)

        # Allowed extensions and extended valid extensions
        valid_extensions = ['txt', 'exe', 'dll', 'zip', 'pdf', 'jpg', 'png']
        extended_valid_extensions = valid_extensions + ['ten', 'wow', 'wow']  # Adding more extensions as example

        extension_score_map = {
            'txt': 1.0,
            'exe': 3.0,
            'dll': 2.0,
            'zip': 2.0,
            'pdf': 1.0,
            'jpg': 2.0,
            'png': 2.0
        }

        # Validate extension if dot is present
        if is_dot_present:
            if extension.lower() not in valid_extensions:
                validation_errors.append(f"Invalid file extension: '{extension}'. Must be one of {valid_extensions}.")
                extension_score = 0.0
            else:
                extension_score = extension_score_map.get(extension.lower(), 0.0)
        else:
            extension_score = 0.0

        # Check if base name is empty
        if not base_name:
            validation_errors.append('Substring before the dot cannot be empty.')
            is_valid = False

        # Check if base name starts with a letter
        if base_name and not base_name[0].isalpha():
            validation_errors.append('Substring before the dot must start with a letter.')
            starts_with_letter = False
        else:
            starts_with_letter = True

        # Check for unsupported special characters
        allowed_chars = string.ascii_letters + string.digits + '_-'
        for ch in base_name:
            if ch not in allowed_chars:
                validation_errors.append('Base name contains unsupported special characters (only underscores and hyphens allowed besides alphanumeric).')
                break

        # Count digits and calculate digit product
        digit_count = 0
        digit_product = 1
        for ch in base_name:
            if ch.isdigit():
                digit_count += 1
                digit_product *= int(ch)

        if digit_count == 0:
            digit_product = 1

        # Calculate base name character score and count of alphabetic characters
        base_name_char_score = 0
        alpha_char_count = 0
        non_alpha_numeric_count = 0

        for ch in base_name:
            if ch.isalpha():
                base_name_char_score += (ord(ch.lower()) - ord('a') + 1)
                alpha_char_count += 1
            elif ch.isdigit():
                # digits don't contribute to char score
                continue
            elif ch in ['_', '-']:
                continue
            else:
                non_alpha_numeric_count += 1

        # Validate minimum alphanumeric characters in base name
        if base_name and alpha_char_count + digit_count < 2:
            validation_errors.append('Base name must contain at least two alphanumeric characters.')
            min_alphanumeric_met = False
        elif not base_name:
            min_alphanumeric_met = False
        else:
            min_alphanumeric_met = True

        # Final validity
        if not validation_errors:
            is_valid = True

        return {
            'is_valid': is_valid,
            'validation_errors': validation_errors,
            'base_name': base_name,
            'extension': extension,
            'total_chars': total_chars,
            'base_name_char_score': base_name_char_score,
            'base_name_digit_product': digit_product,
            'digit_count': digit_count,
            'extension_score': extension_score,
            'alpha_char_count': alpha_char_count,
            'non_alpha_numeric_count': non_alpha_numeric_count,
            'is_dot_present': is_dot_present,
            'starts_with_letter': starts_with_letter,
            'base_name_length': base_name_length,
            'min_alphanumeric_met': min_alphanumeric_met
        }



