modified = []
for i, x in enumerate(lst):
    if i % 3 == 0:
        modified.append(x ** 2)
    elif i % 4 == 0:
        modified.append(x ** 3)
    else:
        modified.append(x)

s = ''
for num in modified:
    if num != 0:
        s += str(abs(num))

unique_chars = len(set(s))
total = sum(modified)
return unique_chars * total

