for length in range(2, n + 1):
    for s in range(max_sum + 1):
        if s - 1 >= 0:
            dp_end[length][s] += dp_end_prefix[length - 1][s - 1]

# Count numbers that start with 1 or end with 1
# We must avoid double counting numbers that both start and end with 1
# Count start only, end only, and both start and end with 1

# Count numbers that start and end with 1
# For length 1, number '1' counted in both start and end
# For length > 1, digits between first and last can be 0..9
# sum of digits = 1 (first) + middle sum + 1 (last) = middle sum + 2

dp_start_end = [[0] * (max_sum + 1) for _ in range(n + 1)]
if n >= 1:
    dp_start_end[1][2] = 1  # number '1' counted as sum=2? No, sum=1+1=2 but length=1 means only one digit '1', sum=1
    # So for length=1, start and end with 1 is just '1' sum=1
    dp_start_end[1][1] = 1

for length in range(3, n + 1):
    # middle length = length - 2
    # build dp for middle digits with leading digit can be zero
    dp_middle = [[0] * (max_sum + 1) for _ in range(length - 1)]
    # length 1 middle digits: digits 0..9
    for d in range(10):
        dp_middle[1][d] = 1
    for l in range(2, length - 1):
        for s in range(max_sum + 1):
            if dp_middle[l - 1][s] == 0:
                continue
            for digit in range(10):
                if s + digit <= max_sum:
                    dp_middle[l][s + digit] += dp_middle[l - 1][s]
    # Now sum over dp_middle[length-2][sum_middle]
    for sum_middle in range(max_sum + 1):
        total_sum = sum_middle + 2  # first and last digits are 1
        if total_sum <= max_sum:
            dp_start_end[length][total_sum] += dp_middle[length - 2][sum_middle]

# For length=2, start and end with 1 means number '11' sum=2
if n >= 2:
    dp_start_end[2][2] = 1

result = 0
for s in range(max_sum + 1):
    if primes[s]:
        count_start = dp_start[n][s]
        count_end = dp_end[n][s]
        count_both = dp_start_end[n][s]
        result += count_start + count_end - count_both

return result

