        # Initialize the result dictionary
        result = {
            'is_valid': False,
            'validation_errors': [],
            'base_name': '',
            'extension': '',
            'total_chars': len(file_name),
            'base_name_char_score': 0,
            'base_name_digit_product': 1,
            'digit_count': 0,
            'extension_score': 0.0,
            'alpha_char_count': 0,
            'non_alpha_numeric_count': 0,
            'is_dot_present': '.' in file_name,
            'starts_with_letter': False,
            'base_name_length': 0,
            'min_alphanumeric_met': False
        }

        # Split the file name into base name and extension
        if '.' in file_name:
            parts = file_name.rsplit('.', 1)
            result['base_name'] = parts[0]
            result['extension'] = parts[1].lower()
        else:
            result['base_name'] = file_name
            result['extension'] = ''

        # Check if the base name is empty
        if not result['base_name']:
            result['validation_errors'].append('Substring before the dot cannot be empty.')

        # Check if the base name starts with a letter
        if result['base_name'] and not result['base_name'][0].isalpha():
            result['validation_errors'].append('Substring before the dot must start with a letter.')
        else:
            result['starts_with_letter'] = True

        # Check for valid extension
        if result['extension'] and result['extension'] not in valid_extensions:
            result['validation_errors'].append(f"Invalid file extension: '{result['extension]}'. Must be one of {valid_extensions}.")
        elif result['extension'] in extension_scores:
            result['extension_score'] = extension_scores[result['extension']]

        # Calculate base name length
        result['base_name_length'] = len(result['base_name'])

        # Check for minimum alphanumeric character count in the base name
        if result['base_name_length'] < 2:
            result['validation_errors'].append('Base name must contain at least two alphanumeric characters.')
        else:
            result['min_alphanumeric_met'] = True

        # Calculate base name char score and digit product
        for char in result['base_name']:
            if char.isalpha():
                result['base_name_char_score'] += string.ascii_lowercase.index(char.lower()) + 1
                result['alpha_char_count'] += 1
            elif char.isdigit():
                result['base_name_digit_product'] *= int(char)
                result['digit_count'] += 1
            elif char not in ('_', '-'):
                result['non_alpha_numeric_count'] += 1

        # Check for too many digits in the base name
        if result['digit_count'] > 3:
            result['validation_errors'].append(f'Base name has too many digits ({result["digit_count"]}), maximum is 3.')

        # Check for unsupported special characters in the base name
        if result['non_alpha_numeric_count'] > 0:
            result['validation_errors'].append('Base name contains unsupported special characters (only underscores and hyphens allowed besides alphanumeric).')

        # Check for exactly one dot in the file name
        if result['is_dot_present'] and file_name.count('.') != 1:
            result['validation_errors'].append('File name must contain exactly one dot.')

        # Set is_valid to True if there are no validation errors
        if not result['validation_errors']:
            result['is_valid'] = True

        return result



