def add_elements(arr, k):
    """
    Given a non-empty array of integers arr and an integer k, this function returns
    the sum of elements from the first k elements of arr that both:
    - have at most two digits
    - have a digit sum equal to the n-th prime Fibonacci number where n is the count of such elements found

    This integrates the idea of prime Fibonacci numbers and adds complexity by introducing digit sum requirements.
    """

    import math

    def is_prime(p: int) -> bool:
        if p < 2:
            return False
        for x in range(2, int(math.isqrt(p)) + 1):
            if p % x == 0:
                return False
        return True

    def prime_fib(n: int) -> int:
        fib = [0, 1]
        count = 0
        while True:
            fib.append(fib[-1] + fib[-2])
            if is_prime(fib[-1]):
                count += 1
            if count == n:
                return fib[-1]

    valid_elements = []
    for elem in arr[:k]:
        if len(str(abs(elem))) <= 2:
            valid_elements.append(elem)

    result = 0
    for idx, val in enumerate(valid_elements, start=1):
        digit_sum = sum(int(d) for d in str(abs(val)))
        pfib = prime_fib(idx)
        if digit_sum == pfib:
            result += val

    return result


